import Link from "next/link";
import { ArrowLeft, Mail, MapPin, Phone, ShieldCheck } from "lucide-react";
import { notFound } from "next/navigation";
import { PageShell } from "@/components/page-shell";
import { DataUnavailable } from "@/components/data-unavailable";
import { VendorStatus } from "@/components/vendor-directory";
import { getVendor } from "@/lib/vendor-repository";
import { formatRate, isRateStale } from "@/lib/vendors";

// @next-codemod-ignore Cache Components adoption: this segment temporarily allows blocking.
export const instant = false;

export default async function VendorDetailPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const result = await getVendor(slug);
  if (result.error) return <PageShell><DataUnavailable message={result.error} /></PageShell>;
  const vendor = result.vendor;
  if (!vendor) notFound();
  const isApproved = vendor.verificationStatus === "approved";
  return <PageShell><Link href="/vendors" className="inline-flex items-center gap-2 text-sm font-semibold text-[var(--primary)] hover:underline"><ArrowLeft size={16} /> All vendors</Link><div className="mt-7 max-w-3xl"><div className="flex flex-wrap items-center gap-2"><p className="text-xs font-bold uppercase tracking-[0.16em] text-[var(--secondary-strong)]">Vendor profile</p><VendorStatus status={vendor.verificationStatus} /></div><h1 className="mt-3 text-4xl font-bold tracking-tight text-[var(--primary-strong)]">{vendor.businessName}</h1><p className="mt-4 flex items-center gap-2 text-base text-[var(--muted-foreground)]"><MapPin size={18} />{vendor.locality}, {vendor.city}, {vendor.state}</p><p className="mt-4 text-base leading-7 text-[var(--muted-foreground)]">{vendor.businessDescription}</p></div>{!isApproved && <div className="mt-7 flex gap-3 rounded-2xl border border-[#f1dfaa] bg-[#fffaf0] p-5 text-sm leading-6 text-[#7b5a08]"><ShieldCheck className="mt-0.5 shrink-0" size={20} /><p><strong>This is not a verified listing.</strong> It is demonstration content and must not be treated as a real vendor recommendation.</p></div>}<div className="mt-8 grid gap-5 lg:grid-cols-[1fr_0.8fr]"><section className="rounded-2xl border border-[var(--border)] bg-white p-6"><h2 className="text-xl font-bold text-[var(--primary-strong)]">Accepted materials and rates</h2><p className="mt-2 text-sm leading-6 text-[var(--muted-foreground)]">All prices shown are indicative and may change. Confirm current rates and acceptance directly before collection.</p><div className="mt-5 space-y-3">{vendor.materials.map((material) => <div key={material.materialSlug} className="rounded-xl bg-[var(--surface)] p-4"><div className="flex items-start justify-between gap-3"><h3 className="font-bold text-[var(--primary-strong)]">{material.materialName}</h3><span className="text-right text-sm font-bold text-[var(--primary-strong)]">{formatRate(material.indicativeRateInrPerKg)}{material.indicativeRateInrPerKg !== null && isRateStale(material.rateLastUpdated) && <span className="block text-[11px] font-medium text-[#9a7310]">May be outdated</span>}</span></div><div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-[var(--muted-foreground)]"><span>{material.minimumCollectionKg === null ? "Minimum quantity: Ask vendor" : `Minimum: ${material.minimumCollectionKg} kg`}</span><span>{material.rateLastUpdated ? `Updated ${material.rateLastUpdated}` : "Rate date unavailable"}</span></div></div>)}{vendor.materials.length === 0 && <p className="rounded-xl bg-[var(--surface)] p-4 text-sm text-[var(--muted-foreground)]">Accepted material details are not available.</p>}</div></section><aside className="space-y-5"><section className="rounded-2xl border border-[var(--border)] bg-white p-6"><h2 className="font-bold text-[var(--primary-strong)]">Service areas</h2><ul className="mt-4 space-y-2 text-sm leading-6 text-[var(--muted-foreground)]">{vendor.serviceAreas.length ? vendor.serviceAreas.map((area) => <li key={area}>• {area}</li>) : <li>Contact vendor for service area.</li>}</ul><p className="mt-5 text-xs text-[var(--muted-foreground)]">Public locality only. Private addresses are not displayed.</p></section><section className="rounded-2xl border border-[var(--border)] bg-white p-6"><h2 className="font-bold text-[var(--primary-strong)]">Contact options</h2>{vendor.publicPhone || vendor.publicEmail ? <div className="mt-4 space-y-3 text-sm">{vendor.publicPhone && <a href={`tel:${vendor.publicPhone}`} className="flex items-center gap-2 font-semibold text-[var(--primary)] hover:underline"><Phone size={16} />{vendor.publicPhone}</a>}{vendor.publicEmail && <a href={`mailto:${vendor.publicEmail}`} className="flex items-center gap-2 font-semibold text-[var(--primary)] hover:underline"><Mail size={16} />{vendor.publicEmail}</a>}</div> : <p className="mt-3 text-sm leading-6 text-[var(--muted-foreground)]">Contact details will appear here only after a vendor provides verified public contact information.</p>}<p className="mt-5 text-xs text-[var(--muted-foreground)]">Directory record updated {vendor.updatedAt.slice(0, 10)}</p></section></aside></div></PageShell>;
}
